type LearnerWorkspacePayload = { enrolments: Array<{ id: string; course_id: string; status: string; enrolled_at: string; completed_at: string | null }>; courses: Array<{ id: string; slug: string; title: string; description: string; subject: string; level: string; language: string; status: string; created_at: string; updated_at: string }>; modules: Array<{ id: string; course_id: string; title: string; sort_order: number }>; lessons: Array<{ id: string; module_id: string; title: string; description: string | null; duration_seconds?: number | null; transcript: string | null; media_path: string | null; sort_order?: number; status: string; is_preview: boolean }>; progress: Array<{ lesson_id: string; status: string; progress_percent: number; last_position_seconds?: number; updated_at?: string }> };
type InstructorStructurePayload = { course: { id: string; title: string; status: string }; modules: Array<{ id: string; course_id: string; title: string; description?: string | null; sort_order: number; status: string }>; lessons: Array<{ id: string; module_id: string; title: string; description?: string | null; duration_seconds?: number | null; transcript?: string | null; media_path?: string | null; sort_order: number; status: string; is_preview: boolean }> };
function Shell({ children, eyebrow }: { children: React.ReactNode; eyebrow?: string }) {
  const { t } = useLocale();
  // The instructor sidebar already carries the brand, the module name and the way back.
  const hasChrome = useHasDashboardChrome();
  if (hasChrome) return <div className={shell}>{children}</div>;
  return <div className={shell}><header className="border-b border-[var(--ni-sage)] bg-[var(--ni-field)]"><div className="mx-auto flex max-w-7xl items-center justify-between gap-4 px-5 py-5 lg:px-8"><Link href="/dashboard/instructor" className="font-display text-2xl">Zufishan <span className="ml-2 text-xs font-sans uppercase tracking-[.18em] ni-t-gold">{eyebrow ?? t("courseStudio.builder")}</span></Link><Link href="/dashboard/instructor" className="text-sm font-bold ni-t-moss">{t("courseStudio.backToDashboard")}</Link></div></header>{children}</div>; }
function LearnerShell({ children, eyebrow = "Learning desk", backHref = "/dashboard/learner", backLabel = "Back to dashboard" }: { children: React.ReactNode; eyebrow?: string; backHref?: string; backLabel?: string }) {
  // Same as Shell: the strip is for the public enrolment and preview routes, which have no chrome.
  const hasChrome = useHasDashboardChrome();
  if (hasChrome) return <div className={shell}>{children}</div>;
  return <div className={shell}><header className="border-b border-[var(--ni-sage)] bg-[var(--ni-field)]"><div className="mx-auto flex max-w-7xl items-center justify-between gap-4 px-5 py-5 lg:px-8"><Link href={backHref} className="font-display text-2xl">Zufishan <span className="ml-2 text-xs font-sans uppercase tracking-[.18em] ni-t-gold">{eyebrow}</span></Link><Link href={backHref} className="text-sm font-bold ni-t-moss">{backLabel}</Link></div></header>{children}</div>; }
function Badge({ status }: { status: CourseRecord["status"] }) { const copy = courseStatusCopy[status]; const tone = copy.tone === "red" ? "bg-[var(--ni-clay-soft)] ni-t-clay" : copy.tone === "gold" ? "bg-[var(--ni-gold-soft)] ni-t-gold" : copy.tone === "sage" ? "bg-[var(--ni-sage-soft)] ni-t-sage-ink" : "bg-[var(--ni-sage-soft)] ni-t-sage-ink"; return <span className={`rounded-full px-3 py-1 text-[11px] font-bold uppercase tracking-[.12em] ${tone}`}>{copy.label}</span>; }
function DemoNotice({ children }: { children?: React.ReactNode }) { return <div className="rounded-2xl border border-[var(--ni-gold-mid)] bg-[var(--ni-gold-soft)] px-5 py-4 text-sm leading-6 ni-t-gold">{children}</div>; }
function EmptyState({ title, copy, action }: { title: string; copy: string; action?: React.ReactNode }) { return <div className="rounded-[1.4rem] border border-dashed border-[var(--ni-sage-mid)] bg-[var(--ni-sage-soft)] p-10 text-center"><BookOpen className="mx-auto ni-t-gold"/><h2 className="mt-4 font-display text-3xl">{title}</h2><p className="mx-auto mt-3 max-w-xl text-sm leading-6 ni-t-muted">{copy}</p>{action && <div className="mt-6">{action}</div>}</div>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block text-sm font-semibold ni-t-moss-deep">{label}{children}</label>; }

/**
 * Publish, on the instructor's own course list.
 *
 * "Publish" submits the course for review — it does not make it public. Only a reviewer's
 * decision can do that, and the `courses_status_guard` trigger refuses any other route, so
 * the button cannot overstate what it does even if this label were wrong. The helper line
 * says so in plain words rather than leaving the instructor to discover it.
 *
 * Shown only where submitting is actually possible: a draft, or a course that came back
 * rejected and has been edited. A course already in review shows its state instead of a
 * button that would do nothing.
 */
function CoursePublishAction({ course, onDone }: { course: InstructorCourseRow; onDone: () => void }) {
  const { t } = useLocale();
  const publishCourse = trpc.supabaseCore.publishCourse.useMutation();
  const unpublishCourse = trpc.supabaseCore.unpublishCourse.useMutation();
  const [notice, setNotice] = useState("");
  const [failed, setFailed] = useState("");

  const live = course.status === "published";
  const verified = course.verification_status === "approved";
  const busy = publishCourse.isPending || unpublishCourse.isPending;

  const run = async (which: "publish" | "unpublish") => {
    setNotice(""); setFailed("");
    try {
      const result = which === "publish"
        ? await publishCourse.mutateAsync({ courseId: course.id })
        : await unpublishCourse.mutateAsync({ courseId: course.id });
      if (!result.ok) { setFailed(result.error); return; }
      setNotice(t(which === "publish" ? "course.publishedNotice" : "course.unpublishedNotice"));
      onDone();
    } catch {
      setFailed(t("course.publishFailed"));
    }
  };

  return (
    <span className="flex flex-wrap items-center gap-2">
      <button
        type="button"
        onClick={() => void run(live ? "unpublish" : "publish")}
        disabled={busy}
        className={live
          ? "rounded-full border border-[var(--ni-sage-line)] px-4 py-2 text-xs font-bold ni-t-ink disabled:opacity-60"
          : "rounded-full bg-[var(--ni-gold)] px-4 py-2 text-xs font-bold text-[var(--ni-on-gold)] disabled:opacity-60"}
      >
        {busy ? t("common.loading") : t(live ? "course.unpublish" : "course.publish")}
      </button>

      {/* The mark, and the honest line beside it while there is not one yet. */}
      {live && (verified
        ? <span className="inline-flex items-center gap-1 ni-label" style={{ color: "var(--ni-moss-deep)" }}>
            <BadgeCheck size={14} aria-hidden="true" /> {t("marketplace.verified")}
          </span>
        : <span className="text-xs ni-t-muted">{t("course.liveNotVerified")}</span>)}

      {notice && <span role="status" className="text-xs font-semibold ni-t-moss">{notice}</span>}
      {failed && <span role="alert" className="text-xs ni-t-clay-ink">{failed}</span>}
    </span>
  );
}

export function InstructorCoursesPage() { const { t } = useLocale(); const { user } = useAuth(); const online = useOnlineStatus(); const query = trpc.supabaseCore.courses.useQuery(undefined, { enabled: Boolean(user), retry: false }); /* A refusal or a server fault used to render as "no courses yet", which reads as the studio being empty rather than the read having failed. */ const state = resultState(query as never, online); const rows = resultRows<InstructorCourseRow>(query as never); return <Shell eyebrow={t("courseStudio.instructorCourses")}><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><h1 className="sr-only">{t("courseStudio.instructorCourses")}</h1><div className="flex flex-wrap items-end justify-end gap-5"><Link href="/dashboard/instructor/courses/new" className="inline-flex items-center gap-2 rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white"><Plus size={16}/> {t("courseStudio.builder")}</Link></div><div className="empty:hidden mt-8">{!user ? <DemoNotice>{t("courseStudio.signInRequired")}</DemoNotice> : query.isLoading ? <p className="rounded-2xl bg-[var(--ni-sage-soft)] px-5 py-4 text-sm">{t("courseStudio.checkingRecords")}</p> : query.data?.ok ? null : <DemoNotice>{t("courseStudio.saveError")}</DemoNotice>}</div>{state !== "ready" && state !== "empty" ? <div className="mt-8"><ResultState state={state} message={resultError(query as never)} onRetry={() => query.refetch()} retrying={query.isFetching}/></div> : rows.length === 0 ? <div className="mt-8"><EmptyState title={user ? t("courseStudio.courseUnavailable") : t("courseStudio.signInRequired")} copy={user ? "Create a draft course to begin. Core course fields persist through the authenticated Supabase builder." : "Connect Supabase Auth before creating or editing a course."} action={user ? <Link href="/dashboard/instructor/courses/new" className="rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white">{t("courseStudio.draftCreated")}</Link> : undefined}/></div> : <div className="mt-8 grid gap-5 lg:grid-cols-3">{rows.map((course) => <article key={course.id} className="rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6 shadow-[0_14px_40px_rgba(37,77,60,.05)]"><div className="flex items-start justify-between gap-3"><span className="text-xs font-bold uppercase tracking-[.14em] ni-t-gold">{course.status.replaceAll("_", " ")}</span><Badge status={course.status as CourseRecord["status"]}/></div><h2 className="mt-5 font-display text-2xl">{course.title}</h2><p className="mt-2 text-sm leading-6 ni-t-muted">{course.description || "No description yet."}</p><div className="mt-5 grid grid-cols-2 gap-3 text-xs ni-t-muted"><div><strong>Subject</strong><p>{course.subject}</p></div><div><strong>Level</strong><p>{course.level}</p></div><div><strong>Language</strong><p>{course.language}</p></div><div><strong>Updated</strong><p>{new Date(course.updated_at).toLocaleDateString()}</p></div></div><div className="mt-6 flex flex-wrap items-center gap-2"><Link href={`/dashboard/instructor/courses/${course.id}/edit`} className="rounded-full bg-[var(--ni-sage-soft)] px-4 py-2 text-xs font-bold">Edit</Link><Link href={`/dashboard/instructor/courses/${course.id}/modules`} className="rounded-full bg-[var(--ni-sage-soft)] px-4 py-2 text-xs font-bold">Structure</Link><CoursePublishAction course={course} onDone={() => query.refetch()}/></div></article>)}</div>}</main></Shell>; }

export function CourseBuilder({ courseId, isNew = false }: { courseId?: string; isNew?: boolean }) { const { t } = useLocale(); const { user } = useAuth(); const [, setLocation] = useLocation(); const coursesQuery = trpc.supabaseCore.courses.useQuery(undefined, { enabled: Boolean(user) }); const create = trpc.supabaseCore.createCourse.useMutation(); const update = trpc.supabaseCore.updateCourse.useMutation(); const submit = trpc.supabaseCore.submitCourseForReview.useMutation(); const [title, setTitle] = useState(""); const [slug, setSlug] = useState(""); const [subject, setSubject] = useState("Tajweed"); const [level, setLevel] = useState("beginner"); const [language, setLanguage] = useState("English"); const [description, setDescription] = useState(""); const [notice, setNotice] = useState(""); const existing = coursesQuery.data?.ok ? (coursesQuery.data.data as InstructorCourseRow[]).find((item) => item.id === courseId) : undefined; useEffect(() => { if (!existing) return; setTitle(existing.title); setSlug(existing.slug); setSubject(existing.subject); setLevel(existing.level); setLanguage(existing.language); setDescription(existing.description); }, [existing?.id]); const save = async () => { setNotice(""); try { if (existing) { const result = await update.mutateAsync({ courseId: existing.id, title, slug, subject, level, language, description }); if (!result.ok) throw new Error(result.error); setNotice(t("courseStudio.draftSaved")); } else { const result = await create.mutateAsync({ title, slug, subject, level, language, description }); if (!result.ok) throw new Error(result.error); setNotice(t("courseStudio.draftCreated")); setLocation(`/dashboard/instructor/courses/${(result.data as { id: string }).id}/edit`); } } catch (error) { setNotice(error instanceof Error ? error.message : t("courseStudio.saveError")); } }; const submitForReview = async () => { if (!existing) { setNotice(t("courseStudio.saveFirst")); return; } try { const result = await submit.mutateAsync({ courseId: existing.id }); if (!result.ok) throw new Error(result.error); setNotice(t("courseStudio.submitted")); } catch (error) { setNotice(error instanceof Error ? error.message : t("courseStudio.submitError")); } }; if (!user) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title={t("courseStudio.signInRequired")} copy={t("courseStudio.authCopy")}/></main></Shell>; if (coursesQuery.isLoading) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title={t("courseStudio.loadingBuilder")} copy={t("courseStudio.checkingRecords")}/></main></Shell>; if (courseId && !existing && !isNew) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title={t("courseStudio.courseUnavailable")} copy={t("courseStudio.notOwnedCopy")}/></main></Shell>; return <Shell eyebrow={existing?.status === "published" ? "Course revision" : "Course builder"}><main className="mx-auto max-w-5xl px-5 py-12 lg:px-8 lg:py-16"><Link href="/dashboard/instructor/courses" className="inline-flex items-center gap-2 text-sm font-bold ni-t-moss"><ArrowLeft size={15}/> {t("courseStudio.allCourses")}</Link><div className="mt-8 flex flex-wrap items-end justify-between gap-4"><div><h1 className={existing ? "font-display text-4xl" : "sr-only"}>{existing ? existing.title : t("courseStudio.builder")}</h1></div>{existing && <Badge status={existing.status as CourseRecord["status"]}/>}</div><div className="mt-8 grid gap-7 lg:grid-cols-[1fr_.42fr]"><section className="rounded-[1.4rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-7"><div className="space-y-5"><Field label="Course title"><input value={title} onChange={(e) => setTitle(e.target.value)} className="input"/></Field><Field label="Slug"><input value={slug} onChange={(e) => setSlug(e.target.value)} className="input" placeholder="tajweed-foundations"/></Field><div className="grid gap-5 sm:grid-cols-3"><Field label="Subject"><input value={subject} onChange={(e) => setSubject(e.target.value)} className="input"/></Field><Field label="Level"><select value={level} onChange={(e) => setLevel(e.target.value)} className="input"><option value="beginner">Beginner</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option><option value="children">Children</option></select></Field><Field label="Teaching language"><select value={language} onChange={(e) => setLanguage(e.target.value)} className="input"><option>English</option><option>Urdu</option><option>Arabic</option><option>English + Urdu</option></select></Field></div><Field label="Course description"><textarea value={description} onChange={(e) => setDescription(e.target.value)} className="input min-h-40"/></Field></div><div className="mt-6 rounded-xl bg-[var(--ni-sage-soft)] p-4 text-sm"><strong>Media boundary:</strong> thumbnail and lesson media metadata are persisted only through authorized Storage procedures. No browser upload or public URL is fabricated here.</div>{notice && <p className="mt-6 rounded-xl bg-[var(--ni-sage-soft)] p-4 text-sm" role="status">{notice}</p>}<div className="mt-7 flex flex-wrap gap-3"><button onClick={save} disabled={create.isPending || update.isPending} className="inline-flex items-center gap-2 rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white disabled:opacity-50"><Save size={15}/> {t("courseStudio.draftSaved")}</button>{existing && <button onClick={submitForReview} disabled={submit.isPending} className="rounded-full border border-[var(--ni-sage-mid)] px-5 py-3 text-sm font-bold ni-t-moss">{t("courseStudio.submitted")}</button>}</div></section><aside className="space-y-5"><div className="rounded-[1.4rem] bg-[var(--ni-teal)] p-6 text-white"><ShieldCheck className="ni-t-gold-mid"/><h2 className="mt-4 font-display text-2xl">A safe publishing path.</h2><p className="mt-3 text-sm leading-6 text-[var(--ni-sage-line)]">{t("course.builderPath")}</p></div>{existing && <div className="rounded-[1.4rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><p className="text-xs font-bold uppercase tracking-[.16em] ni-t-gold">Course structure</p><p className="mt-3 text-sm leading-6 ni-t-muted">Modules and lessons persist through the authenticated builder workspace.</p><Link href={`/dashboard/instructor/courses/${existing.id}/modules`} className="mt-4 inline-flex rounded-full bg-[var(--ni-sage-soft)] px-4 py-2 text-xs font-bold">Manage structure</Link></div>}</aside></div></main></Shell>; }

function StructureCard({ course, module, onRefresh }: { course: CourseRecord; module: CourseModule; onRefresh: () => void }) { const [title, setTitle] = useState(module.title); const [description, setDescription] = useState(module.description); const [notice, setNotice] = useState(""); const move = (direction: "up" | "down") => { const index = course.modules.findIndex((item) => item.id === module.id); const target = direction === "up" ? index - 1 : index + 1; if (target < 0 || target >= course.modules.length) return; const ids = course.modules.map((item) => item.id); [ids[index], ids[target]] = [ids[target], ids[index]]; reorderModules(course.id, ids); onRefresh(); }; return <article className="rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.14em] ni-t-gold">Module {module.moduleOrder}</p><h2 className="mt-2 font-display text-2xl">{module.title}</h2></div><span className="rounded-full bg-[var(--ni-sage-soft)] px-3 py-1 text-xs font-bold">{module.lessons.length} lessons</span></div><div className="mt-5 grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><input value={title} onChange={(e) => setTitle(e.target.value)} aria-label="Module title" className="input"/><input value={description} onChange={(e) => setDescription(e.target.value)} aria-label="Module description" className="input"/><button onClick={() => { const result = updateModule(course.id, module.id, { title, description }); setNotice(result.ok ? "Module saved." : result.error || "Module not saved."); onRefresh(); }} className="rounded-xl bg-[var(--ni-sage-soft)] px-4 py-2 text-xs font-bold">Save</button></div><div className="mt-5 space-y-2">{module.lessons.map((lesson) => <div key={lesson.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-[var(--ni-sage-soft)] px-4 py-3 text-sm"><span><strong>{lesson.lessonOrder}. {lesson.title}</strong><span className="ml-2 text-xs ni-t-muted">{lessonContentLabels[lesson.contentType]} · {lesson.durationMinutes} min</span></span><div className="flex gap-2"><Link href={`/dashboard/instructor/courses/${course.id}/lessons`} className="text-xs font-bold ni-t-moss">Edit</Link>{lesson.isPreview && <span className="text-xs font-bold ni-t-gold">Preview</span>}</div></div>)}</div><div className="mt-5 flex flex-wrap gap-2"><Link href={`/dashboard/instructor/courses/${course.id}/lessons`} className="inline-flex items-center gap-2 rounded-full bg-[var(--ni-moss)] px-4 py-2 text-xs font-bold text-white"><Plus size={14}/> Add lesson</Link><button onClick={() => move("up")} className="rounded-full border border-[var(--ni-sage-mid)] p-2" aria-label="Move module up"><ChevronUp size={15}/></button><button onClick={() => move("down")} className="rounded-full border border-[var(--ni-sage-mid)] p-2" aria-label="Move module down"><ChevronDown size={15}/></button><button onClick={() => { if (window.confirm("Delete this draft module and its lessons?")) { const result = deleteModule(course.id, module.id); setNotice(result.ok ? "Draft module deleted." : result.error || "Module not deleted."); onRefresh(); } }} className="rounded-full bg-[var(--ni-clay-soft)] p-2 ni-t-clay" aria-label="Delete draft module"><Trash2 size={15}/></button></div>{notice && <p className="mt-4 text-xs ni-t-muted" role="status">{notice}</p>}</article>; }
export function CourseModulesPage({ courseId, lessonsOnly = false }: { courseId: string; lessonsOnly?: boolean }) { const { user } = useAuth(); const query = trpc.supabaseCore.structure.useQuery({ courseId }, { enabled: Boolean(user) }); const createModule = trpc.supabaseCore.createModule.useMutation(); const createLesson = trpc.supabaseCore.createLesson.useMutation(); const deleteModule = trpc.supabaseCore.deleteModule.useMutation(); const deleteLesson = trpc.supabaseCore.deleteLesson.useMutation(); const [moduleTitle, setModuleTitle] = useState(""); const [lessonTitle, setLessonTitle] = useState(""); const [selectedModule, setSelectedModule] = useState(""); const [notice, setNotice] = useState(""); const structure = query.data?.ok ? query.data.data as InstructorStructurePayload : null; const refresh = () => query.refetch(); if (!user) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Sign in required" copy="Course structure is available only to the authenticated instructor owner."/></main></Shell>; if (query.isLoading) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Loading course structure" copy="Checking owned modules and lessons…"/></main></Shell>; if (!structure) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Course not available" copy="The course is not owned by the signed-in instructor or persistence is unavailable."/></main></Shell>; const modules = structure.modules; const lessons = structure.lessons; const addModule = async () => { try { const result = await createModule.mutateAsync({ courseId, title: moduleTitle, sortOrder: modules.length }); if (!result.ok) throw new Error(result.error); setModuleTitle(""); setNotice("Module saved to Supabase."); await refresh(); } catch (error) { setNotice(error instanceof Error ? error.message : "Module could not be saved."); } }; const addLesson = async () => { if (!selectedModule) { setNotice("Choose a module before saving a lesson."); return; } try { const result = await createLesson.mutateAsync({ moduleId: selectedModule, title: lessonTitle, sortOrder: lessons.filter((item) => item.module_id === selectedModule).length }); if (!result.ok) throw new Error(result.error); setLessonTitle(""); setNotice("Lesson metadata saved to Supabase. Media upload remains provider-gated."); await refresh(); } catch (error) { setNotice(error instanceof Error ? error.message : "Lesson could not be saved."); } }; return <Shell eyebrow={lessonsOnly ? "Lesson studio" : "Course structure"}><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><Link href={`/dashboard/instructor/courses/${courseId}/edit`} className="inline-flex items-center gap-2 text-sm font-bold ni-t-moss"><ArrowLeft size={15}/> Back to builder</Link><div className="mt-8"><h1 className="font-display text-4xl">{structure.course.title}</h1></div><div className="mt-8 grid gap-7 lg:grid-cols-[.72fr_1.28fr]"><section className="space-y-5">{!lessonsOnly && <div className="rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><p className="text-xs font-bold uppercase tracking-[.16em] ni-t-gold">Add module</p><div className="mt-4 flex gap-2"><input value={moduleTitle} onChange={(e) => setModuleTitle(e.target.value)} className="input" placeholder="Foundations"/><button onClick={addModule} className="rounded-full bg-[var(--ni-moss)] px-4 py-2 text-xs font-bold text-white"><Plus size={15}/></button></div></div>}<div className="rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><p className="text-xs font-bold uppercase tracking-[.16em] ni-t-gold">Add lesson</p><div className="mt-4 space-y-3"><select value={selectedModule} onChange={(e) => setSelectedModule(e.target.value)} className="input"><option value="">Select module</option>{modules.map((module) => <option key={module.id} value={module.id}>{module.title}</option>)}</select><input value={lessonTitle} onChange={(e) => setLessonTitle(e.target.value)} className="input" placeholder="A calm first recitation"/><button onClick={addLesson} className="inline-flex items-center gap-2 rounded-full bg-[var(--ni-moss)] px-4 py-3 text-sm font-bold text-white"><Plus size={15}/> Save lesson metadata</button></div><p className="mt-4 text-xs leading-5 ni-t-muted">Lesson title, transcript, preview flag, and private media path are stored only through authorized server procedures. No fake upload success is shown.</p></div>{notice && <p className="rounded-xl bg-[var(--ni-sage-soft)] p-4 text-sm" role="status">{notice}</p>}</section><section className="space-y-4">{modules.length === 0 ? <EmptyState title="No modules yet" copy="Create the first module to begin the course structure."/> : modules.map((module) => <article key={module.id} className="rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] ni-t-gold">Module {module.sort_order + 1}</p><h2 className="mt-2 font-display text-2xl">{module.title}</h2></div><button onClick={async () => { const result = await deleteModule.mutateAsync({ moduleId: module.id }); setNotice(result.ok ? "Draft module deleted." : result.error); await refresh(); }} className="rounded-full bg-[var(--ni-clay-soft)] p-2 ni-t-clay" aria-label="Delete draft module"><Trash2 size={14}/></button></div><div className="mt-4 space-y-2">{lessons.filter((lesson) => lesson.module_id === module.id).map((lesson) => <div key={lesson.id} className="flex items-center justify-between gap-3 rounded-xl bg-[var(--ni-sage-soft)] p-3 text-sm"><span>{lesson.title}</span><span className="text-xs ni-t-muted">{lesson.status}{lesson.media_path ? " · media metadata" : " · media pending"}</span><button onClick={async () => { const result = await deleteLesson.mutateAsync({ lessonId: lesson.id }); setNotice(result.ok ? "Draft lesson deleted." : result.error); await refresh(); }} className="rounded-full bg-[var(--ni-clay-soft)] p-2 ni-t-clay" aria-label="Delete draft lesson"><Trash2 size={13}/></button></div>)}</div></article>)}</section></div></main></Shell>; }

function InstructorCoursePreview({ courseId }: { courseId: string }) { const { user } = useAuth(); const courseQuery = trpc.supabaseCore.courses.useQuery(undefined, { enabled: Boolean(user) }); const structureQuery = trpc.supabaseCore.structure.useQuery({ courseId }, { enabled: Boolean(user) }); const course = courseQuery.data?.ok ? (courseQuery.data.data as InstructorCourseRow[]).find((item) => item.id === courseId) : undefined; const structure = structureQuery.data?.ok ? (structureQuery.data.data as InstructorStructurePayload) : undefined; if (!user) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Sign in required" copy="Course preview is available only to the authenticated instructor owner."/></main></Shell>; if (courseQuery.isLoading || structureQuery.isLoading) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Loading course preview" copy="Reading the protected course structure…"/></main></Shell>; if (!course || !structure) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Course preview unavailable" copy="The course is not owned by the signed-in instructor or its structure could not be read."/></main></Shell>; return <Shell eyebrow="Course preview"><main className="mx-auto max-w-5xl px-5 py-12 lg:px-8 lg:py-16"><Link href={`/dashboard/instructor/courses/${course.id}/edit`} className="inline-flex items-center gap-2 text-sm font-bold ni-t-moss"><ArrowLeft size={15}/> Back to builder</Link><h1 className="mt-8 font-display text-4xl">{course.title}</h1><p className="mt-4 max-w-2xl leading-7 ni-t-muted">{course.description || "Full description pending."}</p><div className="mt-8 rounded-[1.4rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-7"><p className="text-sm ni-t-muted">{course.subject} · {course.level} · {course.language} · {course.status}</p><h2 className="mt-7 font-display text-3xl">Course structure</h2><div className="mt-5 space-y-4">{structure.modules.length === 0 ? <p className="rounded-xl bg-[var(--ni-sage-soft)] p-4 text-sm ni-t-muted">No connected modules are available yet.</p> : structure.modules.map((module) => <section key={module.id} className="rounded-xl bg-[var(--ni-sage-soft)] p-5"><h3 className="font-display text-2xl">{module.title}</h3><p className="mt-2 text-sm ni-t-muted">{module.description || "Module description pending."}</p><div className="mt-4 space-y-2">{structure.lessons.filter((lesson) => lesson.module_id === module.id).map((lesson) => <div key={lesson.id} className="rounded-lg bg-[var(--ni-paper)] p-3 text-sm"><span className="font-semibold">{lesson.title}</span><span className="ml-2 ni-t-muted">{lesson.status}{lesson.is_preview ? " · Preview" : ""}</span></div>)}</div></section>)}</div></div></main></Shell>; }

export function CoursePreviewPage({ courseId, publicView = false }: { courseId: string; publicView?: boolean }) { if (!publicView) return <InstructorCoursePreview courseId={courseId}/>; const course = getCourseById(courseId); if (!course || (publicView && course.status !== "published")) return <LearnerShell backHref={publicView ? "/courses" : "/dashboard/instructor/courses"} backLabel={publicView ? "Browse courses" : "Back to courses"}><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Course not available" copy="Only published course information is visible to public users."/></main></LearnerShell>; const lessons = flattenPublishedLessons(course); const PreviewShell = publicView ? LearnerShell : Shell; return <PreviewShell eyebrow={publicView ? "Course detail" : "Course preview"} {...(!publicView ? {} : { backHref: "/courses", backLabel: "Browse courses" })}><main className="mx-auto max-w-6xl px-5 py-12 lg:px-8 lg:py-16"><Link href={publicView ? "/courses" : `/dashboard/instructor/courses/${course.id}/edit`} className="inline-flex items-center gap-2 text-sm font-bold ni-t-moss"><ArrowLeft size={15}/> {publicView ? "All courses" : "Back to builder"}</Link><div className="mt-8 grid gap-8 lg:grid-cols-[1.1fr_.7fr]"><section><div className="overflow-hidden rounded-[1.5rem] bg-[var(--ni-teal)]"><img src={displayableImageSrc(course.thumbnailPath) || "/brand/course-geometry.svg"} alt="" className="h-64 w-full object-cover opacity-75"/><div className="p-8 text-white"><p className="text-xs font-bold uppercase tracking-[.18em] ni-t-gold-mid">{course.subject} · {course.level}</p><h1 className="mt-4 font-display text-5xl">{course.title}</h1><p className="mt-4 max-w-2xl leading-7 text-[var(--ni-sage-line)]">{course.description}</p></div></div><div className="mt-6 grid gap-4 sm:grid-cols-3"><div className="rounded-2xl bg-[var(--ni-sage-soft)] p-5"><p className="text-xs font-bold uppercase tracking-[.14em] ni-t-gold">Language</p><p className="mt-2 font-semibold">{course.language}</p></div><div className="rounded-2xl bg-[var(--ni-sage-soft)] p-5"><p className="text-xs font-bold uppercase tracking-[.14em] ni-t-gold">Format</p><p className="mt-2 font-semibold">{course.format.replaceAll("_", " ")}</p></div><div className="rounded-2xl bg-[var(--ni-sage-soft)] p-5"><p className="text-xs font-bold uppercase tracking-[.14em] ni-t-gold">Effort</p><p className="mt-2 font-semibold">{course.weeklyEffort || "To be set"}</p></div></div><div className="mt-8"><h2 className="font-display text-3xl">Learning outcomes</h2><ul className="mt-4 grid gap-3 sm:grid-cols-2">{course.learningOutcomes.map((outcome) => <li key={outcome} className="flex gap-3 rounded-xl bg-[var(--ni-paper)] p-4 text-sm"><Check className="shrink-0 ni-t-moss" size={18}/>{outcome}</li>)}</ul></div><div className="mt-8"><h2 className="font-display text-3xl">Course outline</h2><div className="mt-4 space-y-3">{course.modules.length === 0 ? <p className="rounded-xl bg-[var(--ni-sage-soft)] p-4 text-sm ni-t-muted">Course outline coming soon.</p> : course.modules.map((module) => <details key={module.id} className="rounded-2xl border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-5" open><summary className="cursor-pointer list-none font-display text-2xl">{module.moduleOrder}. {module.title}</summary><p className="mt-2 text-sm leading-6 ni-t-muted">{module.description}</p><div className="mt-4 space-y-2">{module.lessons.filter((lesson) => !publicView || lesson.status === "published").map((lesson) => <div key={lesson.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-[var(--ni-sage-soft)] p-3 text-sm"><span>{lesson.lessonOrder}. {lesson.title}</span><span className="text-xs ni-t-muted">{lessonContentLabels[lesson.contentType]} · {lesson.durationMinutes} min {lesson.isPreview && "· Preview"}</span></div>)}</div></details>)}</div></div></section><aside className="h-fit space-y-5"><div className="rounded-[1.4rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.16em] ni-t-gold">Instructor</p><span className="rounded-full bg-[var(--ni-gold-soft)] px-3 py-1 text-xs font-bold">Verification pending</span></div><h2 className="mt-4 font-display text-3xl">{course.instructorName}</h2><p className="mt-2 text-sm ni-t-muted">Public teaching context · {course.language}</p><Link href={`/teachers/${course.instructorSlug}`} className="mt-4 inline-flex text-sm font-bold ni-t-moss">View instructor profile <ArrowRight size={15} className="ml-1 inline"/></Link></div><div className="rounded-[1.4rem] bg-[var(--ni-gold-soft)] p-6"><p className="text-xs font-bold uppercase tracking-[.16em] ni-t-gold">Access</p><h2 className="mt-3 font-display text-3xl">{course.accessType === "free" ? "Free enrolment" : course.accessType === "paid" ? `${course.priceAmount || "Price"} ${course.currency || ""}` : "Coming soon"}</h2><p className="mt-3 text-sm leading-6 ni-t-gold">{course.accessType === "paid" ? "Payment integration coming soon. No charge or enrolment is created here." : "Course access is clearly labelled while connected enrolment is prepared."}</p>{publicView && <div className="mt-5 flex flex-wrap gap-2"><Link href={`/enrol/${course.id}`} className="rounded-full bg-[var(--ni-moss)] px-4 py-3 text-sm font-bold text-white">Enrol</Link><TrialCTA context={{ courseSlug: course.slug, instructorSlug: course.instructorSlug }} label="Request trial"/></div>}</div>{publicView && <div className="rounded-[1.4rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><p className="text-sm ni-t-muted">Rating and reviews will appear after authentic learner feedback exists. No ratings are fabricated in demo mode.</p><button onClick={() => undefined} className="mt-4 rounded-full border border-[var(--ni-sage-mid)] px-4 py-2 text-xs font-bold">Save course placeholder</button></div>}<div className="rounded-[1.4rem] bg-[var(--ni-sage-soft)] p-6"><p className="text-xs font-bold uppercase tracking-[.16em] ni-t-gold">Preview lesson</p><p className="mt-3 font-display text-2xl">{course.previewLessonId ? getLesson(course.previewLessonId)?.title : "Preview to be selected"}</p><p className="mt-2 text-sm leading-6 ni-t-muted">{course.previewLessonId ? "Preview access is available only through an authorised lesson route." : "The instructor has not selected a preview lesson yet."}</p></div></aside></div></main></PreviewShell>; }

export function PublicCourseDetail({ slug }: { slug: string }) { const course = getCourseBySlug(slug); return course ? <CoursePreviewPage courseId={course.id} publicView/> : <LearnerShell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Course not found" copy="This course is not part of the public catalogue." action={<Link href="/courses" className="rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white">Browse courses</Link>}/></main></LearnerShell>; }
export function CourseSubmitPage({ courseId }: { courseId: string }) { const { user } = useAuth(); const query = trpc.supabaseCore.courses.useQuery(undefined, { enabled: Boolean(user) }); const submit = trpc.supabaseCore.submitCourseForReview.useMutation(); const [notice, setNotice] = useState(""); const course = query.data?.ok ? (query.data.data as InstructorCourseRow[]).find((item) => item.id === courseId) : undefined; if (!user) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Sign in required" copy="Moderation submission requires the authenticated instructor owner."/></main></Shell>; if (query.isLoading) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Loading submission" copy="Checking the protected course record…"/></main></Shell>; if (!course) return <Shell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Course not available" copy="The course is not owned by the signed-in instructor or is no longer available."/></main></Shell>; const submitCourse = async () => { try { const result = await submit.mutateAsync({ courseId }); if (!result.ok) throw new Error(result.error); setNotice("Course submitted for moderation. No direct publish or reviewer decision is claimed."); } catch (error) { setNotice(error instanceof Error ? error.message : "Course could not be submitted."); } }; return <Shell eyebrow="Moderation submission"><main className="mx-auto max-w-3xl px-5 py-12 lg:px-8 lg:py-16"><Link href={`/dashboard/instructor/courses/${course.id}/edit`} className="inline-flex items-center gap-2 text-sm font-bold ni-t-moss"><ArrowLeft size={15}/> Back to builder</Link><div className="mt-7 rounded-[1.4rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-7"><div className="flex items-center justify-between gap-3"><h2 className="font-display text-3xl">{course.title}</h2><Badge status={course.status as CourseRecord["status"]}/></div><p className="mt-4 text-sm leading-6 ni-t-muted">{course.description || "Full description pending."}</p><p className="mt-5 rounded-xl bg-[var(--ni-sage-soft)] p-4 text-sm">Only draft or rejected courses can request review. Publication and reviewer decisions remain separate protected operations.</p>{notice && <p className="mt-5 rounded-xl bg-[var(--ni-sage-soft)] p-4 text-sm" role="status">{notice}</p>}<div className="mt-7"><CoursePassMarkField courseId={courseId} current={(course as { pass_mark?: number | null }).pass_mark ?? null}/></div><button onClick={submitCourse} disabled={submit.isPending || !["draft", "rejected"].includes(course.status)} className="mt-7 rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white disabled:opacity-50">{submit.isPending ? "Submitting…" : "Submit for review"}</button></div></main></Shell>; }

export function EnrolPage({ courseId }: { courseId: string }) { const [, setLocation] = useLocation(); const { user } = useAuth(); const courseQuery = trpc.supabaseCore.publicCourseById.useQuery({ courseId }); const createEnrollment = trpc.supabaseCore.createEnrolment.useMutation(); const [notice, setNotice] = useState(""); const course = courseQuery.data?.ok ? courseQuery.data.data as PublicCourseRow : null; if (courseQuery.isLoading) return <LearnerShell eyebrow="Enrolment"><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Loading enrolment" copy="Checking the published course record…"/></main></LearnerShell>; if (!course) return <LearnerShell eyebrow="Enrolment"><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Course unavailable" copy="Only published Supabase course records can be enrolled in. No demo course is substituted." action={<Link href="/courses" className="rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white">Browse courses</Link>}/></main></LearnerShell>; if (!user) return <LearnerShell eyebrow="Enrolment"><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Sign in before enrolling" copy="Your enrolment belongs to an authenticated learner. Nothing is created until Supabase Auth is connected." action={<Link href={`/login?returnTo=/enrol/${course.id}`} className="rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white">Continue to login</Link>}/></main></LearnerShell>; const submit = async () => { try { const result = await createEnrollment.mutateAsync({ courseId: course.id }); if (!result.ok) throw new Error(result.error); setLocation(`/dashboard/learner/courses/${course.id}`); } catch (error) { setNotice(error instanceof Error ? error.message : "Enrolment could not be created. No demo enrolment was written."); } }; return <LearnerShell eyebrow="Enrolment"><main className="mx-auto max-w-3xl px-5 py-12 lg:px-8 lg:py-16"><Link href={`/courses/${course.slug}`} className="inline-flex items-center gap-2 text-sm font-bold ni-t-moss"><ArrowLeft size={15}/> Back to course</Link><p className="mt-8 text-xs font-bold uppercase tracking-[.2em] ni-t-gold">Published course</p><h1 className="mt-3 font-display text-5xl">Confirm your place in {course.title}.</h1><div className="mt-7 rounded-[1.4rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-7"><p className="text-sm leading-6 ni-t-muted">{course.subject} · {course.level} · {course.language}</p><div className="mt-5 rounded-xl bg-[var(--ni-sage-soft)] p-4 text-sm"><p><strong>Access:</strong> Enrolment is available only through the connected LMS policy.</p><p className="mt-2"><strong>Terms:</strong> Course access and progress are subject to authenticated enrolment and RLS checks.</p></div><p className="mt-5 rounded-xl bg-[var(--ni-gold-soft)] p-4 text-sm ni-t-gold">Payment and paid access are not configured. This action never charges a learner or claims payment success.</p>{notice && <p className="mt-5 rounded-xl bg-[var(--ni-clay-soft)] p-4 text-sm ni-t-clay" role="status">{notice}</p>}<button onClick={submit} disabled={createEnrollment.isPending} className="mt-7 rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white disabled:opacity-50">{createEnrollment.isPending ? "Creating enrolment…" : "Create enrolment"}</button></div></main></LearnerShell>; }

/**
 * Courses the learner could join, inside the Courses module.
 *
 * The module listed enrolments only, so a course an administrator had just approved had
 * nowhere to appear here — the learner had to leave the dashboard for the public
 * catalogue to discover it existed. That is the gap this closes.
 *
 * It reuses `schedulingPublic.publishedCourses`, the SAME procedure the public catalogue
 * calls, rather than adding a second listing. Everything that decides eligibility is
 * already behind it: the row must be `published`, and policy 0031 additionally requires
 * the owning instructor to be approved. Nothing is filtered here for security — the only
 * thing removed is what the learner already holds, which would otherwise be listed twice.
 */
function AvailableCourses({ enrolledIds }: { enrolledIds: Set<string> }) {
  const { t } = useLocale();
  const online = useOnlineStatus();
  const query = trpc.schedulingPublic.publishedCourses.useQuery(undefined, { retry: false });
  const state = resultState(query as never, online);

  type Row = { id: string; slug: string; title: string; description: string; subject: string; level: string; language: string };
  const all: Row[] = query.data?.ok ? ((query.data.data as { courses?: Row[] }).courses ?? []) : [];
  const rows = all.filter((course) => !enrolledIds.has(course.id));

  return (
    <section className="mt-12 border-t border-[var(--ni-sage)] pt-8">
      <h2 className="font-display text-3xl ni-t-ink">{t("catalogue.publishedCourses")}</h2>
      <p className="mt-2 max-w-2xl text-sm leading-6 ni-t-muted">{t("catalogue.publicFieldsOnly")}</p>

      <div className="mt-6">
        {state !== "ready" && state !== "empty" ? (
          <ResultState state={state} message={resultError(query as never)} onRetry={() => query.refetch()} retrying={query.isFetching}/>
        ) : rows.length === 0 ? (
          <ResultState state="empty" message={t("catalogue.courseDiscoveryUnavailable")}/>
        ) : (
          <div className="grid gap-5 md:grid-cols-2">
            {rows.map((course) => (
              <article key={course.id} className="rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6">
                <p className="text-xs font-bold uppercase tracking-[.14em] ni-t-gold">{course.subject}</p>
                <h3 className="mt-2 font-display text-2xl ni-t-ink">{course.title}</h3>
                <p className="mt-2 line-clamp-3 text-sm leading-6 ni-t-muted">{course.description}</p>
                <div className="mt-4 flex flex-wrap gap-2 text-xs ni-t-muted">
                  <span className="ni-verify">{course.level}</span>
                  <span className="ni-verify">{course.language}</span>
                </div>
                <Link href={`/courses/${course.slug}`} className="mt-5 inline-flex items-center gap-2 rounded-full bg-[var(--ni-moss)] px-4 py-2 text-sm font-bold text-white">
                  {t("home.viewCourse")} <ArrowRight size={15}/>
                </Link>
              </article>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

export function LearnerCoursesPage() { const { t } = useLocale(); const { user } = useAuth(); const online = useOnlineStatus(); const query = trpc.supabaseCore.learnerWorkspace.useQuery(undefined, { enabled: Boolean(user), retry: false }); const state = resultState(query as never, online); const workspace = query.data?.ok ? query.data.data as LearnerWorkspacePayload : null; const progressByLesson = new Map((workspace?.progress ?? []).map((row) => [row.lesson_id, row])); const rows = (workspace?.enrolments ?? []).map((enrolment) => { const course = workspace?.courses.find((item) => item.id === enrolment.course_id); if (!course) return null; const moduleIds = new Set((workspace?.modules ?? []).filter((item) => item.course_id === course.id).map((item) => item.id)); const lessons = (workspace?.lessons ?? []).filter((item) => moduleIds.has(item.module_id) && item.status === "published"); const completed = lessons.filter((lesson) => progressByLesson.get(lesson.id)?.status === "completed").length; return { course, enrolment, percent: lessons.length ? Math.round(completed / lessons.length * 100) : 0, completed, total: lessons.length }; }).filter((row): row is NonNullable<typeof row> => row !== null); if (!user) return <LearnerShell eyebrow={t("dashboard.learningDesk")}><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title={t("catalogue.courseDiscoveryUnavailable")} copy={t("dashboard.noAuthorized")} action={<Link href="/courses" className="rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white">{t("dashboard.exploreCourses")}</Link>}/></main></LearnerShell>; if (query.isLoading) return <LearnerShell eyebrow="My courses"><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title={t("catalogue.loadingPublished")} copy={t("dashboard.notice")}/></main></LearnerShell>; if (!workspace) return <LearnerShell eyebrow="My courses"><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title={t("catalogue.courseDiscoveryUnavailable")} copy={`${t("dashboard.noAuthorized")}.`}/></main></LearnerShell>; return <LearnerShell eyebrow="My courses"><main className="mx-auto max-w-6xl px-5 py-12 lg:px-8 lg:py-16"><h1 className="sr-only">{t("nav.courses")}</h1>{state !== "ready" && state !== "empty" ? <div className="mt-8"><ResultState state={state} message={resultError(query as never)} onRetry={() => query.refetch()} retrying={query.isFetching}/></div> : rows.length === 0 ? <div className="mt-8"><EmptyState title={t("dashboard.nothingConnected")} copy={t("dashboard.noAuthorized")} action={<Link href="/courses" className="rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white">Explore courses</Link>}/></div> : <div className="mt-8 grid gap-5 md:grid-cols-2">{rows.map((row) => <article key={row.course.id} className="rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.14em] ni-t-gold">{row.enrolment.status}</p><h2 className="mt-2 font-display text-3xl">{row.course.title}</h2></div><span className="font-display text-2xl ni-t-moss">{row.percent}%</span></div><p className="mt-3 text-sm ni-t-muted">{row.course.subject} · {row.course.level} · {row.course.language}</p><div className="mt-5 h-2 rounded-full bg-[var(--ni-sage)]"><div className="h-full rounded-full bg-[var(--ni-moss)]" style={{ width: `${row.percent}%` }}/></div><p className="mt-3 text-xs ni-t-muted">{row.completed} of {row.total} {t("dashboard.nothingConnected")}</p><Link href={`/dashboard/learner/courses/${row.course.id}`} className="mt-5 inline-flex items-center gap-2 rounded-full bg-[var(--ni-moss)] px-4 py-2 text-sm font-bold text-white">{t("footer.learn")} <ArrowRight size={15}/></Link></article>)}</div>}<AvailableCourses enrolledIds={new Set(rows.map((row) => row.course.id))}/></main></LearnerShell>; }

export function LearnerWorkspace({ courseId }: { courseId: string }) { const { user } = useAuth(); const query = trpc.supabaseCore.learnerWorkspace.useQuery(undefined, { enabled: Boolean(user) }); const workspace = query.data?.ok ? query.data.data as LearnerWorkspacePayload : null; const course = workspace?.courses.find((item) => item.id === courseId); const enrolment = workspace?.enrolments.find((item) => item.course_id === courseId); const progressByLesson = new Map((workspace?.progress ?? []).map((row) => [row.lesson_id, row])); const modules = (workspace?.modules ?? []).filter((item) => item.course_id === courseId); const lessons = (workspace?.lessons ?? []).filter((item) => modules.some((module) => module.id === item.module_id) && item.status === "published"); const completed = lessons.filter((lesson) => progressByLesson.get(lesson.id)?.status === "completed").length; const next = lessons.find((lesson) => progressByLesson.get(lesson.id)?.status !== "completed") ?? lessons[0]; if (!user) return <LearnerShell eyebrow="Course workspace"><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Sign in required" copy="This workspace is available only through authenticated Supabase enrolment access."/></main></LearnerShell>; if (query.isLoading) return <LearnerShell eyebrow="Course workspace"><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Loading workspace" copy="Checking your enrolment, lesson access, and progress…"/></main></LearnerShell>; if (!course || !enrolment) return <LearnerShell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Enrolment required" copy="This protected workspace is available only for an authenticated active or completed enrolment." action={<Link href="/courses" className="rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white">Browse courses</Link>}/></main></LearnerShell>; return <LearnerShell eyebrow="Course workspace"><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><Link href="/dashboard/learner/courses" className="inline-flex items-center gap-2 text-sm font-bold ni-t-moss"><ArrowLeft size={15}/> My courses</Link><div className="mt-8 flex flex-wrap items-end justify-between gap-4"><div><h1 className="font-display text-4xl">{course.title}</h1><p className="mt-3 ni-t-muted">{course.subject} · {course.level} · {course.language}</p></div><div className="text-right"><p className="font-display text-4xl ni-t-moss">{lessons.length ? Math.round(completed / lessons.length * 100) : 0}%</p><p className="text-xs ni-t-muted">{completed}/{lessons.length} complete</p></div></div><div className="mt-8"><DemoNotice>Lesson access and progress are read and written through authenticated Supabase procedures. Private media remains signed-URL and provider gated.</DemoNotice></div><div className="mt-8 grid gap-7 lg:grid-cols-[.7fr_1.3fr]"><aside className="space-y-4">{modules.map((module) => <div key={module.id} className="rounded-2xl border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-5"><p className="text-xs font-bold uppercase tracking-[.14em] ni-t-gold">Module {module.sort_order + 1}</p><h2 className="mt-2 font-display text-2xl">{module.title}</h2><div className="mt-4 space-y-2">{lessons.filter((lesson) => lesson.module_id === module.id).map((lesson) => { const progress = progressByLesson.get(lesson.id); return <Link key={lesson.id} href={`/dashboard/learner/lessons/${lesson.id}`} className="flex items-center justify-between gap-3 rounded-xl bg-[var(--ni-sage-soft)] px-3 py-3 text-sm"><span>{lesson.title}</span><span className="text-xs ni-t-muted">{progress?.status === "completed" ? "Done" : lesson.is_preview ? "Preview" : "Open"}</span></Link>; })}</div></div>)}</aside><section className="space-y-5"><div className="rounded-[1.5rem] bg-[var(--ni-teal)] p-8 text-white"><p className="text-xs font-bold uppercase tracking-[.18em] ni-t-gold-mid">Continue learning</p><h2 className="mt-4 font-display text-4xl">{next?.title || "Course complete"}</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[var(--ni-sage-line)]">{next?.description || "Your connected progress record has no remaining published lessons."}</p>{next && <Link href={`/dashboard/learner/lessons/${next.id}`} className="mt-6 inline-flex items-center gap-2 rounded-full bg-[var(--ni-gold-soft)] px-5 py-3 text-sm font-bold ni-t-ink">Open lesson <PlayCircle size={16}/></Link>}</div><div className="grid gap-4 sm:grid-cols-2"><div className="rounded-2xl border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><FileText className="ni-t-moss"/><h2 className="mt-4 font-display text-2xl">Assignments and quizzes</h2><p className="mt-2 text-sm leading-6 ni-t-muted">Assessment persistence is connected to the LMS schema; scoring and reviewer workflows remain setup-needed.</p></div><div className="rounded-2xl border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><ShieldCheck className="ni-t-moss"/><h2 className="mt-4 font-display text-2xl">Certificate status</h2>{/* The placeholder here said no certificate could be generated. The rule exists now, so this reports the real decision the server makes. */}<div className="mt-4"><EligibilityPanel courseId={courseId}/></div></div></div></section></div></main></LearnerShell>; }

export function LearnerLessonPage({ lessonId }: { lessonId: string }) { const { user } = useAuth(); const query = trpc.supabaseCore.learnerWorkspace.useQuery(undefined, { enabled: Boolean(user) }); const updateProgress = trpc.supabaseCore.updateProgress.useMutation(); const workspace = query.data?.ok ? query.data.data as LearnerWorkspacePayload : null; const lesson = workspace?.lessons.find((item) => item.id === lessonId && item.status === "published"); const module = workspace?.modules.find((item) => item.id === lesson?.module_id); const course = workspace?.courses.find((item) => item.id === module?.course_id); const enrolment = workspace?.enrolments.find((item) => item.course_id === course?.id); const progress = workspace?.progress.find((item) => item.lesson_id === lessonId); const [notice, setNotice] = useState(""); if (!user) return <LearnerShell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Sign in required" copy="Lesson access is protected by authenticated enrolment checks."/></main></LearnerShell>; if (query.isLoading) return <LearnerShell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Loading lesson" copy="Checking authorized course access…"/></main></LearnerShell>; if (!lesson || !module || !course || !enrolment) return <LearnerShell><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title="Lesson unavailable" copy="This lesson is not published, enrolled, or available to the signed-in learner."/></main></LearnerShell>; const saveProgress = async (completed: boolean) => { try { const result = await updateProgress.mutateAsync({ lessonId, completed, progressPercent: completed ? 100 : Math.max(progress?.progress_percent ?? 0, 1) }); if (!result.ok) throw new Error(result.error); setNotice("Progress saved to Supabase."); await query.refetch(); } catch (error) { setNotice(error instanceof Error ? error.message : "Progress could not be saved."); } }; return <LearnerShell eyebrow="Lesson"><main className="mx-auto max-w-4xl px-5 py-12 lg:px-8 lg:py-16"><Link href={`/dashboard/learner/courses/${course.id}`} className="inline-flex items-center gap-2 text-sm font-bold ni-t-moss"><ArrowLeft size={15}/> Back to workspace</Link><div className="mt-8 rounded-[1.5rem] bg-[var(--ni-teal)] p-8 text-white"><p className="text-xs font-bold uppercase tracking-[.18em] ni-t-gold-mid">{course.title} · {module.title}</p><h1 className="mt-4 font-display text-5xl">{lesson.title}</h1><p className="mt-4 text-sm leading-7 text-[var(--ni-sage-line)]">{lesson.description || "Connected lesson content."}</p></div><div className="mt-7 rounded-2xl border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6"><p className="text-xs font-bold uppercase tracking-[.16em] ni-t-gold">Lesson content</p><p className="mt-4 whitespace-pre-wrap text-sm leading-7 ni-t-moss-deep">{lesson.transcript || "Transcript and media content are not configured for this lesson yet."}</p><div className="mt-6 rounded-xl bg-[var(--ni-sage-soft)] p-4 text-sm"><strong>Private media:</strong> {lesson.media_path ? "Metadata exists; signed media delivery remains protected." : "No media metadata is configured."}</div><div className="mt-6 flex flex-wrap gap-3"><button onClick={() => saveProgress(false)} disabled={updateProgress.isPending} className="rounded-full border border-[var(--ni-sage-mid)] px-5 py-3 text-sm font-bold ni-t-moss">Mark in progress</button><button onClick={() => saveProgress(true)} disabled={updateProgress.isPending} className="rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white">Complete lesson</button></div>{notice && <p className="mt-4 text-sm" role="status">{notice}</p>}</div></main></LearnerShell>; }

export function PublicLessonPreview({ slug, lessonId }: { slug: string; lessonId: string }) {
  const { t } = useLocale();
  const query = trpc.supabaseCore.publicLessonMetadata.useQuery({ slug, lessonId });
  const payload = (query.data?.ok ? query.data.data : null) as PublicLessonMetadataPayload | null;
  if (query.isLoading) return <LearnerShell eyebrow={t("catalogue.courseDiscoveryUnavailable")} backHref={`/courses/${slug}`} backLabel={t("dashboard.back")}><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title={t("catalogue.loadingPublished")} copy={t("dashboard.notice")}/></main></LearnerShell>;
  if (!payload) return <LearnerShell eyebrow={t("catalogue.courseDiscoveryUnavailable")} backHref={`/courses/${slug}`} backLabel={t("dashboard.back")}><main className="mx-auto max-w-3xl px-5 py-20"><EmptyState title={t("catalogue.courseDiscoveryUnavailable")} copy={t("catalogue.courseNotPublicCopy")} action={<Link href={`/courses/${slug}`} className="rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-bold text-white">{t("dashboard.back")}</Link>}/></main></LearnerShell>;
  return <LearnerShell eyebrow={payload.course.title} backHref={`/courses/${slug}`} backLabel={t("dashboard.back")}><main className="mx-auto max-w-4xl px-5 py-12 lg:px-8 lg:py-16"><Link href={`/courses/${slug}`} className="inline-flex items-center gap-2 text-sm font-bold ni-t-moss">{t("dashboard.back")}</Link><div className="mt-8 rounded-[1.5rem] bg-[var(--ni-teal)] p-8 text-white"><p className="text-xs font-bold uppercase tracking-[.18em] ni-t-gold-mid">{payload.course.title} · {payload.module?.title ?? payload.course.subject}</p><h1 className="mt-4 font-display text-5xl">{payload.lesson.title}</h1><p className="mt-4 text-sm leading-7 text-[var(--ni-sage-line)]">{payload.lesson.description || t("dashboard.privateCopy")}</p></div><div className="mt-7 rounded-[1.4rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-7"><div className="flex flex-wrap gap-3 text-xs font-bold uppercase tracking-[.14em] ni-t-gold"><span>{payload.lesson.is_preview ? "Preview" : "Published lesson"}</span>{payload.lesson.duration_seconds ? <span>{Math.ceil(payload.lesson.duration_seconds / 60)} min</span> : null}</div><p className="mt-6 whitespace-pre-wrap text-sm leading-7 ni-t-moss-deep">{payload.lesson.transcript || t("dashboard.privateCopy")}</p><p className="mt-6 rounded-xl bg-[var(--ni-sage-soft)] p-4 text-sm leading-6 ni-t-muted">{t("dashboard.privateCopy")}</p></div></main></LearnerShell>;
}
